cmd "prune" {
    help "Delete archived runs of the current namespace for real, freeing their names and disk space"
    long_help "Deletes each selected archived run's archive folder, worktree metadata, local branches and registry entry. Never touches records, remote branches or pull requests. A run whose local branches hold commits no other ref keeps is kept unless --force is set. Prints a preview and asks for confirmation unless --yes or --dry-run is set.\n\nSide effects: deletes under ~/.phax/archive/, deletes local branches, updates ~/.phax/registry.json."
    example "phax prune old-idea"
    example "phax prune --all --dry-run"
    example "phax prune --all --yes"
    arg "[short-name]..." { help "Archived run short name, e.g. old-idea" }
    flag "--all" { help "Prune every archived run of the current namespace" }
    flag "--force" { help "Also prune runs whose branches hold unpreserved commits" }
    flag "--dry-run" { help "Print the preview and delete nothing" }
    flag "--yes -y" { help "Proceed without confirmation" }
    flag "--json" { help "Output as JSON" }
}

